{"type":"javascript","code":"const STATE_FILE = "affinity_state.json";
const DASH_FILE = "affinity_dashboard.html";

const LEVELS = [
  { min: 0,  name: "Stranger",     color: "#8a8f98", desc: "Formal and distant. Only practical, surface-level conversation." },
  { min: 20, name: "Acquaintance", color: "#5aa7ff", desc: "Friendly small talk is welcome; light anecdotes may be shared." },
  { min: 40, name: "Friend",       color: "#4fd08a", desc: "Casual banter, honest opinions, and personal habits. Still guarded about the deep past." },
  { min: 60, name: "Close Friend", color: "#f5c542", desc: "Personal secrets and family history are revealed; more vulnerability." },
  { min: 80, name: "Confidant",    color: "#ef7db5", desc: "The character's deepest truth and full emotional vulnerability. Total trust." }
];

function levelFor(score) {
  let idx = 0;
  for (let i = 0; i < LEVELS.length; i++) { if (score >= LEVELS[i].min) idx = i; }
  return idx;
}

function esc(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

let state = { charName: "the character", history: [], current: 0 };
try {
  const raw = await $read(STATE_FILE);
  if (raw) state = JSON.parse(raw);
} catch (e) { /* first turn */ }

const affinity = Math.max(0, Math.min(100, Math.round(Number(input.affinity) || 0)));
const delta = Math.round(Number(input.delta) || 0);
const reason = String(input.reason || "");
const now = new Date().toISOString();

if (input.char_name) state.charName = String(input.char_name);
state.current = affinity;
state.lastDelta = delta;
state.lastReason = reason;
state.updatedAt = now;
state.history.push({ t: now, score: affinity, delta: delta, reason: reason });
if (state.history.length > 30) state.history = state.history.slice(-30);

await $write(STATE_FILE, JSON.stringify(state, null, 2));

const li = levelFor(affinity);
const cur = LEVELS[li];
const next = LEVELS[li + 1] || null;
const lo = cur.min;
const hi = next ? next.min : 100;
const span = Math.max(1, hi - lo);
const pct = Math.max(0, Math.min(100, Math.round(((affinity - lo) / span) * 100)));

const rows = state.history.slice().reverse().map(h => {
  const d = new Date(h.t);
  const sign = h.delta > 0 ? "+" + h.delta : String(h.delta);
  const cls = h.delta > 0 ? "up" : (h.delta < 0 ? "down" : "flat");
  return `<tr><td>${d.toLocaleTimeString()}</td><td>${esc(sign)}</td><td class="${cls}">${h.score}</td><td class="reason">${esc(h.reason)}</td></tr>`;
}).join("\n");

const pills = LEVELS.map((L, i) => {
  const active = i === li ? "active" : "";
  const unlocked = i <= li ? "unlocked" : "locked";
  return `<div class="pill ${active} ${unlocked}"><span class="dot" style="background:${L.color}"></span>${L.name}<div class="range">${L.min}+</div></div>`;
}).join("\n");

const trend = delta > 0 ? "▲ Rising" : (delta < 0 ? "▼ Falling" : "— Stable");
const trendCls = delta > 0 ? "up" : (delta < 0 ? "down" : "flat");
const deltaLabel = (delta >= 0 ? "+" + delta : String(delta));

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Affinity Dashboard</title>
<style>
  :root { --bg:#0e1116; --card:#161b22; --card2:#1c232e; --line:#2a3441; --text:#e6edf3; --muted:#8b98a5; --accent:${cur.color}; }
  * { box-sizing: border-box; }
  body { margin:0; padding:24px; background:var(--bg); color:var(--text); font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; }
  .wrap { max-width: 860px; margin: 0 auto; }
  h1 { font-size: 20px; margin: 0 0 4px; letter-spacing:.3px; }
  .sub { color: var(--muted); font-size: 13px; margin-bottom: 20px; }
  .card { background: var(--card); border:1px solid var(--line); border-radius:14px; padding:20px; margin-bottom:16px; }
  .top { display:flex; align-items:center; gap:24px; flex-wrap:wrap; }
  .score { font-size:56px; font-weight:700; line-height:1; color:var(--accent); }
  .score small { font-size:16px; color:var(--muted); font-weight:400; }
  .meta { flex:1; min-width:220px; }
  .levelname { font-size:22px; font-weight:600; }
  .trend { font-size:13px; margin-top:4px; }
  .trend.up{color:#4fd08a;} .trend.down{color:#ff6b6b;} .trend.flat{color:var(--muted);}
  .bar { height:14px; background:var(--card2); border-radius:8px; overflow:hidden; margin-top:16px; border:1px solid var(--line); }
  .fill { height:100%; width:${pct}%; background:linear-gradient(90deg, var(--accent), rgba(255,255,255,.2)); transition:width .4s; }
  .barlabel { display:flex; justify-content:space-between; font-size:12px; color:var(--muted); margin-top:6px; }
  .pills { display:flex; gap:10px; flex-wrap:wrap; margin-top:16px; }
  .pill { flex:1; min-width:120px; background:var(--card2); border:1px solid var(--line); border-radius:10px; padding:10px 12px; opacity:.45; }
  .pill.unlocked { opacity:1; }
  .pill.active { border-color: var(--accent); box-shadow:0 0 0 1px var(--accent) inset; }
  .pill .dot { display:inline-block; width:8px; height:8px; border-radius:50%; margin-right:6px; }
  .pill .range { font-size:11px; color:var(--muted); margin-top:4px; }
  .depth { font-size:14px; line-height:1.5; color:var(--text); background:var(--card2); border-left:3px solid var(--accent); border-radius:6px; padding:12px 14px; }
  h2 { font-size:13px; text-transform:uppercase; letter-spacing:.6px; color:var(--muted); margin:0 0 12px; }
  table { width:100%; border-collapse:collapse; font-size:13px; }
  th,td { text-align:left; padding:8px 10px; border-bottom:1px solid var(--line); }
  th { color:var(--muted); font-weight:600; font-size:11px; text-transform:uppercase; letter-spacing:.5px; }
  td.up{color:#4fd08a;font-weight:600;} td.down{color:#ff6b6b;font-weight:600;} td.flat{color:var(--muted);}
  td.reason{color:var(--muted);}
  .footer{color:var(--muted);font-size:12px;text-align:center;margin-top:8px;}
</style>
</head>
<body>
<div class="wrap">
  <h1>💗 Affinity Dashboard</h1>
  <div class="sub">Tracking ${esc(state.charName)} &rarr; You &nbsp;•&nbsp; Updated ${new Date().toLocaleString()}</div>

  <div class="card">
    <div class="top">
      <div class="score">${affinity}<small> / 100</small></div>
      <div class="meta">
        <div class="levelname" style="color:${cur.color}">${cur.name}</div>
        <div class="trend ${trendCls}">${trend} &nbsp;(${deltaLabel} this turn)</div>
      </div>
    </div>
    <div class="bar"><div class="fill"></div></div>
    <div class="barlabel">
      <span>${cur.name} (from ${lo})</span>
      <span>${next ? next.min + " &rarr; " + next.name : "Max level reached"}</span>
    </div>
    <div class="pills">${pills}</div>
  </div>

  <div class="card">
    <h2>Conversation Depth Unlocked</h2>
    <div class="depth">${esc(cur.desc)}</div>
  </div>

  <div class="card">
    <h2>Turn History</h2>
    <table>
      <thead><tr><th>Time</th><th>&Delta;</th><th>Affinity</th><th>Why</th></tr></thead>
      <tbody>${rows || '<tr><td colspan="4" style="color:var(--muted)">No history yet.</td></tr>'}</tbody>
    </table>
  </div>

  <div class="footer">Generated by the record_affinity skill</div>
</div>
</body>
</html>`;

await $write(DASH_FILE, html);

result = {
  dashboard: DASH_FILE,
  affinity: affinity,
  delta: delta,
  level: cur.name,
  levelIndex: li,
  nextLevel: next ? { name: next.name, at: next.min } : null,
  progressToNextPct: pct,
  unlockedDepth: cur.desc,
  historyLength: state.history.length
};"}
